        except Exception:
            return ([], [{'row': 1, 'errors': ['could not read xlsx file']}])
    elif lower.endswith('.csv'):
        try:
            text = data.decode('utf-8-sig')
        except UnicodeDecodeError:
            return ([], [{'row': 1, 'errors': ['csv must be UTF-8 encoded']}])
